create or alter proc [community].[GetChanges] @lvl int as begin declare @dt datetime = null
select @dt = max(ChangeOn) from community.PackageDeploymentHistory
if (@dt is null) begin set @dt = '1/1/1970' end
drop table if exists #environments ; create table #environments (ClientID int, CompanyID int);
insert into #environments select ClientID, ID as CompanyID from Company where EnvironmentLevel = @lvl;
select PV.* from community.PackageVersion PV inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) and ( PV.UpdatedOn >= @dt or exists (select 1 from community.PackageClient where PackageVersionUid = PV.[Uid] and (CreatedOn >= @dt or UpdatedOn >= @dt)) or exists (select 1 from community.Allocation where PackageVersionUid = PV.[Uid] and (CreatedOn >= @dt or UpdatedOn >= @dt)) or exists ( select 1 from community.Allocation A cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.AssetTypeVersion ATV on ATV.Uid = AV.[Uid] where A.PackageVersionUid = PV.[Uid] and (ATV.CreatedOn >= @dt or ATV.UpdatedOn >= @dt) ) or exists ( select 1 from community.Allocation A cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.Asset AA on AA.AssetTypeVersionUid = AV.[Uid] where A.PackageVersionUid = PV.[Uid] and (AA.CreatedOn >= @dt or AA.UpdatedOn >= @dt) ) or exists ( select 1 from community.Allocation A cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] where A.PackageVersionUid = PV.[Uid] and (IT.CreatedOn >= @dt or IT.UpdatedOn >= @dt) ) or exists ( select 1 from community.Allocation A cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] inner join community.[Predicate] P on P.Uid = IT.PredicateUid where A.PackageVersionUid = PV.[Uid] and (P.CreatedOn >= @dt or P.UpdatedOn >= @dt) ) or exists ( select 1 from community.Allocation A cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.[Intersect] I on I.IntersectTypeUid = IV.Uid where A.PackageVersionUid = PV.[Uid] and (I.CreatedOn >= @dt or I.UpdatedOn >= @dt) ) );
select PC.* from community.PackageClient PC where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) and ( PC.UpdatedOn >= @dt or exists (select 1 from community.PackageVersion where Uid = PC.PackageVersionUid and (CreatedOn >= @dt or UpdatedOn >= @dt)) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = PC.PackageVersionUid cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.AssetTypeVersion ATV on ATV.Uid = AV.[Uid] where A.PackageVersionUid = PV.[Uid] and (ATV.CreatedOn >= @dt or ATV.UpdatedOn >= @dt) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = PC.PackageVersionUid cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.Asset AA on AA.AssetTypeVersionUid = AV.[Uid] where A.PackageVersionUid = PV.[Uid] and (AA.CreatedOn >= @dt or AA.UpdatedOn >= @dt) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = PC.PackageVersionUid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] where A.PackageVersionUid = PV.[Uid] and (IT.CreatedOn >= @dt or IT.UpdatedOn >= @dt) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = PC.PackageVersionUid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] inner join community.[Predicate] P on P.Uid = IT.PredicateUid where A.PackageVersionUid = PV.[Uid] and (P.CreatedOn >= @dt or P.UpdatedOn >= @dt) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = PC.PackageVersionUid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.[Intersect] I on I.IntersectTypeUid = IV.Uid where A.PackageVersionUid = PV.[Uid] and (I.CreatedOn >= @dt or I.UpdatedOn >= @dt) ) );
select A.* from community.Allocation A inner join community.PackageVersion OPV on OPV.Uid = A.PackageVersionUid inner join community.PackageClient PC on PC.PackageVersionUid = OPV.Uid where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) and ( A.UpdatedOn >= @dt or exists (select 1 from community.PackageVersion where Uid = A.PackageVersionUid and (CreatedOn >= @dt or UpdatedOn >= @dt)) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = A.PackageVersionUid cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.AssetTypeVersion ATV on ATV.Uid = AV.[Uid] where A.PackageVersionUid = PV.[Uid] and (ATV.CreatedOn >= @dt or ATV.UpdatedOn >= @dt) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = A.PackageVersionUid cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.Asset AA on AA.AssetTypeVersionUid = AV.[Uid] where A.PackageVersionUid = PV.[Uid] and (AA.CreatedOn >= @dt or AA.UpdatedOn >= @dt) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = A.PackageVersionUid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] where A.PackageVersionUid = PV.[Uid] and (IT.CreatedOn >= @dt or IT.UpdatedOn >= @dt) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = A.PackageVersionUid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] inner join community.[Predicate] P on P.Uid = IT.PredicateUid where A.PackageVersionUid = PV.[Uid] and (P.CreatedOn >= @dt or P.UpdatedOn >= @dt) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and PV.Uid = A.PackageVersionUid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.[Intersect] I on I.IntersectTypeUid = IV.Uid where A.PackageVersionUid = PV.[Uid] and (I.CreatedOn >= @dt or I.UpdatedOn >= @dt) ) );
select T.* from community.AssetType T where exists (select 1 from community.AssetTypeVersion where AssetTypeUid = T.Uid and (CreatedOn >= @dt or UpdatedOn >= @dt)) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.AssetTypeVersion ATV on ATV.Uid = AV.[Uid] and ATV.AssetTypeUid = T.Uid and (ATV.CreatedOn >= @dt or ATV.UpdatedOn >= @dt) inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.AssetTypeVersion ATV on ATV.Uid = AV.[Uid] and ATV.AssetTypeUid = T.Uid inner join community.Asset AA on AA.AssetTypeVersionUid = AV.[Uid] and (AA.CreatedOn >= @dt or AA.UpdatedOn >= @dt) inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) )
select V.* from community.AssetTypeVersion V where V.UpdatedOn >= @dt or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid cross apply OPENJSON(A.AssetTypeVersions) with (Uid uniqueidentifier '$') AV inner join community.Asset AA on AA.AssetTypeVersionUid = AV.[Uid] and (AA.CreatedOn >= @dt or AA.UpdatedOn >= @dt) inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where AV.[Uid] = V.Uid and exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) )
select A.* from community.Asset A inner join ( select IV.Uid from community.PackageVersion PV inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid inner join community.Allocation A on A.PackageVersionUid = PV.Uid cross apply OPENJSON(A.AssetTypeVersions) with ([Uid] uniqueidentifier '$') IV where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) ) T on T.Uid = A.AssetTypeVersionUid where A.UpdatedOn >= @dt;
select P.* from community.[Predicate] P where UpdatedOn >= @dt or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and (PV.CreatedOn >= @dt or PV.UpdatedOn >= @dt) cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] and IT.PredicateUid = P.Uid inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and (A.CreatedOn >= @dt or A.UpdatedOn >= @dt) cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] and IT.PredicateUid = P.Uid inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.IntersectType IT on IT.Uid = IV.[Uid] and IT.PredicateUid = P.Uid and (IT.CreatedOn >= @dt or IT.UpdatedOn >= @dt) inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) );
select T.* from community.IntersectType T where T.UpdatedOn >= @dt or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where IV.[Uid] = T.[Uid] and (PV.CreatedOn >= @dt or PV.UpdatedOn >= @dt) and exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid and (A.CreatedOn >= @dt or A.UpdatedOn >= @dt) cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where IV.[Uid] = T.[Uid] and exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) ) or exists ( select 1 from community.PackageVersion PV inner join community.Allocation A on A.PackageVersionUid = PV.Uid cross apply OPENJSON(A.IntersectTypes) with (Uid uniqueidentifier '$') IV inner join community.[Intersect] I on I.IntersectTypeUid = IV.[Uid] and (I.CreatedOn >= @dt or I.UpdatedOn >= @dt) inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid where IV.[Uid] = T.[Uid] and exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) );
select I.* from community.[Intersect] I inner join ( select IV.Uid from community.PackageVersion PV inner join community.PackageClient PC on PC.PackageVersionUid = PV.Uid inner join community.Allocation A on A.PackageVersionUid = PV.Uid cross apply OPENJSON(A.IntersectTypes) with ([Uid] uniqueidentifier '$') IV where exists (select 1 from #environments where ClientID = PC.ClientID) and ( (PC.Companies is not null and PC.Companies <> '[]' and exists (select 1 from openjson(PC.Companies) with (ID int '$') C inner join #environments E on E.CompanyID = C.ID)) or (PC.Companies is null or PC.Companies = '[]') ) ) T on T.Uid = I.IntersectTypeUid where I.[State] = 1 and I.UpdatedOn >= @dt; end
